import {db} from './api.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function editEvent(event,month,onSaved){
 let names=[];if(event){const result=await db.from('services').select('name').eq('event_id',event.id).eq('enabled',true).order('sort_order');if(result.error){alert('Unable to load event services. Please try again.');return;}names=result.data.map(s=>s.name);}
 const dialog=document.createElement('dialog');dialog.className='event-editor';dialog.innerHTML=`<h2>${event?'Edit':'Add'} event</h2><form><label class="field">Event name<input name="title" class="input" required maxlength="160" value="${esc(event?.title)}"></label><label class="field">Date<input name="date" class="input" type="date" required value="${event?.event_date||month+'-01'}"></label><label class="field">Campus<select name="campus"><option value="kompally">Kompally</option><option value="eden_square">Eden Square</option></select></label><label class="field">Number of services<select class="input" name="count">${Array.from({length:13},(_,n)=>`<option value="${n}" ${n===names.length?'selected':''}>${n===0?'NA — no service changes':n}</option>`).join('')}</select></label><p class="small muted">Sunday services remain unchanged. On other dates, named event services replace the default list. NA keeps existing services.</p><div class="event-service-names"></div><label class="event-special"><input name="special" type="checkbox" ${event?.special!==false?'checked':''}> Special event</label><p role="status"></p><div class="actions"><button class="btn primary">Save event</button><button class="btn" type="button" data-cancel>Cancel</button></div></form>`;
 document.body.append(dialog);dialog.querySelector('[name="campus"]').value=event?.campus_id||'kompally';const count=dialog.querySelector('[name="count"]'),host=dialog.querySelector('.event-service-names');function fields(){const previous=[...host.querySelectorAll('input')].map(i=>i.value);if(previous.length)names=previous;const n=Number(count.value);if(!Number.isInteger(n)||n<0||n>12)return;host.innerHTML=Array.from({length:n},(_,i)=>`<label class="field">Service ${i+1} name<input class="input" name="service_name" maxlength="80" required value="${esc(names[i]||'')}" placeholder="e.g. Evening service"></label>`).join('');}fields();count.oninput=fields;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.showModal();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;const {error}=await db.rpc('save_calendar_event',{p_id:event?.id||null,p_title:String(f.get('title')).trim(),p_date:f.get('date'),p_campus:f.get('campus'),p_names:f.getAll('service_name').map(s=>s.trim()),p_special:f.has('special')});if(error){dialog.querySelector('[role="status"]').textContent=error.message;button.disabled=false;return;}dialog.close();onSaved(String(f.get('date')).slice(0,7));};
}
export async function deleteEvent(event,onSaved){if(!confirm(`Delete “${event.title}”? Its event services will be hidden. Published schedules prevent deletion.`))return;const {error}=await db.rpc('delete_calendar_event',{p_id:event.id});if(error){alert(error.message);return;}onSaved();}
